extension String {
  func decodeToSMS() -> String? {
    // Translate the string into a Smileys or SMS (Mobile Messaging) format using specific characters, symbols, emojis, etc.
    var result = self

    let maskMap: [Character: Character] = [
      "(": "(", ")": ")", "?": "?", " ": " ", "#": "#",
      "➡️": "➡️", "🔥": "🔥", "@": "@" // Further add more mappings if needed
    ]

    for char in result {
      if let replacedChar = maskMap[char], !replacedChar.isWhitespace && !replacedChar.isPunctuation { // remove extra spaces and punctuations
        result = result.replacingOccurrences(of: String(char), with: String(replacedChar))
      }
    }

    return result
  }
}
